    {"id": "ext_11", "risk": "moderate", "name": "Disable CSRSS Splitting", "category": "Modo Extremo", "desc": "Evita el parpadeo del subsistema cliente-servidor (Reduce Microstutters).", "cmd_apply": "reg add \"HKLM\\SYSTEM\\CurrentControlSet\\Control\\Session Manager\\SubSystems\" /v Windows /t REG_EXPAND_SZ /d \"%SystemRoot%\\system32\\csrss.exe ObjectDirectory=\\Windows SharedSection=1024,20480,768 Windows=On SubSystemType=Windows ServerDll=basesrv,1 ServerDll=winsrv:UserServerDllInitialization,3 ServerDll=sxssrv,4 ProfileControl=Off MaxRequestThreads=16\" /f", "cmd_revert": "echo No automatizado revert csrss"},
    {"id": "ext_12", "risk": "moderate", "name": "TCP Max Syn Retransmissions", "category": "Modo Extremo", "desc": "Corta conexiones de red estancadas en vez de esperar.", "cmd_apply": "reg add \"HKLM\\SYSTEM\\CurrentControlSet\\Services\\Tcpip\\Parameters\" /v TcpMaxDataRetransmissions /t REG_DWORD /d 3 /f", "cmd_revert": "reg delete \"HKLM\\SYSTEM\\CurrentControlSet\\Services\\Tcpip\\Parameters\" /v TcpMaxDataRetransmissions /f"},
    {"id": "ext_13", "risk": "moderate", "name": "USB Selective Suspend Disable", "category": "Modo Extremo", "desc": "Nunca apagar USBs (Fix ratones que se duermen 1ms).", "cmd_apply": "powercfg /SETACVALUEINDEX SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bea128a440 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0", "cmd_revert": "powercfg /SETACVALUEINDEX SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bea128a440 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 1"},
    {"id": "ext_14", "risk": "moderate", "name": "Bypass C-States", "category": "Modo Extremo", "desc": "Fuerza C-State C0 (Procesador siempre al máximo).", "cmd_apply": "powercfg -setacvalueindex scheme_current sub_processor 68f262a7-f621-4069-b9a5-4874169be23c 0", "cmd_revert": "powercfg -setacvalueindex scheme_current sub_processor 68f262a7-f621-4069-b9a5-4874169be23c 1"},
    {"id": "ext_15", "risk": "moderate", "name": "Disable Power Throttling", "category": "Modo Extremo", "desc": "Evita que Windows ralentice apps en fondo.", "cmd_apply": "reg add \"HKLM\\SYSTEM\\CurrentControlSet\\Control\\Power\\PowerThrottling\" /v PowerThrottlingOff /t REG_DWORD /d 1 /f", "cmd_revert": "reg delete \"HKLM\\SYSTEM\\CurrentControlSet\\Control\\Power\\PowerThrottling\" /v PowerThrottlingOff /f"},
    {"id": "ext_16", "risk": "danger", "name": "Disable LUA (UAC)", "category": "Modo Extremo", "desc": "Deshabilita el molesto prompt de Administrador (PELIGRO: Ejecuta virus sin aviso).", "cmd_apply": "reg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\" /v EnableLUA /t REG_DWORD /d 0 /f", "cmd_revert": "reg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\" /v EnableLUA /t REG_DWORD /d 1 /f"},
    {"id": "ext_17", "risk": "danger", "name": "Disable Defender Real-Time", "category": "Modo Extremo", "desc": "Mata el escaneo en tiempo real de Defender (Gran aumento FPS).", "cmd_apply": "reg add \"HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Defender\" /v DisableAntiSpyware /t REG_DWORD /d 1 /f", "cmd_revert": "reg delete \"HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Defender\" /v DisableAntiSpyware /f"},
    {"id": "ext_18", "risk": "moderate", "name": "Disable Transparent Glass", "category": "Modo Extremo", "desc": "Apaga transparencias DWM para ahorrar GPU pura.", "cmd_apply": "reg add \"HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize\" /v EnableTransparency /t REG_DWORD /d 0 /f", "cmd_revert": "reg add \"HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize\" /v EnableTransparency /t REG_DWORD /d 1 /f"},
    {"id": "ext_19", "risk": "moderate", "name": "Force MSI Mode GPU", "category": "Modo Extremo", "desc": "Message Signaled Interrupts en GPU (Reduce latencia PCI-e). Requiere script complejo o manual.", "cmd_apply": "echo Aplicación manual requerida para MSI Mode", "cmd_revert": "echo NA"},
    {"id": "ext_20", "risk": "moderate", "name": "Tickrate 0.5ms", "category": "Modo Extremo", "desc": "Fuerza temporizador de Windows a 0.5ms (Máximo Kernel).", "cmd_apply": "echo Usa ISLC o TimerResolution para forzar 0.5ms globalmente", "cmd_revert": "echo NA"},
    {"id": "ext_21", "risk": "moderate", "name": "Disable Background Layout", "category": "Modo Extremo", "desc": "Evita cálculo de disco de fondo.", "cmd_apply": "reg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer\" /v DisableAutoTray /t REG_DWORD /d 1 /f", "cmd_revert": "reg delete \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer\" /v DisableAutoTray /f"},
    {"id": "ext_22", "risk": "moderate", "name": "Disable MPO (Multi-Plane Overlay)", "category": "Modo Extremo", "desc": "Arregla stutters y pantallazos negros en gráficas NVIDIA/AMD.", "cmd_apply": "reg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\Dwm\" /v OverlayTestMode /t REG_DWORD /d 5 /f", "cmd_revert": "reg delete \"HKLM\\SOFTWARE\\Microsoft\\Windows\\Dwm\" /v OverlayTestMode /f"},
